package Program.service; import Program.model.Income; import Program.utils.FileManager; import java.time.LocalDate; import java.util.*;
public class IncomeService extends TransactionService { public Income add(String user,double amount,String category,LocalDate date,String desc){Income i=new Income(UUID.randomUUID().toString(),user,amount,category,date,desc);FileManager.append("incomes.txt",record(i));return i;} public void update(Income i,double amount,String cat,LocalDate date,String desc){i.setAmount(amount);i.setCategory(cat);i.setDate(date);i.setDescription(desc);FileManager.update("incomes.txt",s->s.startsWith(i.getId()+"|"),record(i));} public void delete(String id){FileManager.delete("incomes.txt",s->s.startsWith(id+"|"));}}
